function extractConstStringArray(source: string, name: string): string[] {
  const match = source.match(new RegExp(`const ${name} = \\[([\\s\\S]*?)\\];`));

  if (!match) {
    throw new Error(`Missing string array constant: ${name}`);
  }

  return [...match[1].matchAll(/"([^"]+)"/g)].map(([, value]) => value);
}

function extractConstStringObject(source: string, name: string): Record<string, string> {
  const match = source.match(new RegExp(`const ${name} = \\{([\\s\\S]*?)\\};`));

  if (!match) {
    throw new Error(`Missing string object constant: ${name}`);
  }

  return Object.fromEntries(
    [...match[1].matchAll(/"([^"]+)":\s*"([^"]+)"/g)].map(([, key, value]) => [
      key,
      value,
    ]),
  );
}

