function readRequiredEnterpriseLiveEvidenceAuditTargetResultKeys() {
  const releaseGateSource = readFileSync(
    join(process.cwd(), "scripts/production-e2e-release-gate.mjs"),
    "utf8",
  );
  const enterpriseLiveEvidenceAuditSource = readFileSync(
    join(process.cwd(), "scripts/enterprise-live-evidence-audit.mjs"),
    "utf8",
  );

  return {
    ...Object.fromEntries(
      Object.entries(enterpriseLiveEvidenceAuditResultConstByAuditTarget).map(
        ([target, constName]) => [
          target,
          extractConstStringArray(enterpriseLiveEvidenceAuditSource, constName),
        ],
      ),
    ),
    ...Object.fromEntries(
      Object.entries(enterpriseLiveEvidenceAuditResultConstByTarget).map(
        ([target, constName]) => [
          target,
          extractConstStringArray(releaseGateSource, constName),
        ],
      ),
    ),
  };
}

