function acceptedSnapshotStorageSchemaHealth() {
  return {
    status: "ready",
    schemaVersion: "matched",
    migrationStatus: "up-to-date",
    snapshotStore: "json-atomic-snapshot",
    auditLog: "jsonl-append-only",
      backupStore: "json-atomic-snapshot",
      restoreDrillLog: "jsonl-append-only",
      revisionControl: "optimistic-revision",
      concurrencyControl: "atomic-rename-with-revision-check",
      productionDatabaseAdapter: {
        status: "ready",
        providerClass: "managed-database",
        migrationStatus: "up-to-date",
        backupPolicy: "point-in-time-restore",
        concurrencyControl: "transactional",
        valueRedacted: true,
      },
      valueRedacted: true,
    };
  }

function acceptedSnapshotStorageHealthResponseShape(prefix: string) {
  return {
    [prefix]: "present",
    [`${prefix}.status`]: "present",
    [`${prefix}.schemaVersion`]: "present",
    [`${prefix}.migrationStatus`]: "present",
    [`${prefix}.snapshotStore`]: "present",
    [`${prefix}.auditLog`]: "present",
    [`${prefix}.backupStore`]: "present",
      [`${prefix}.restoreDrillLog`]: "present",
      [`${prefix}.revisionControl`]: "present",
      [`${prefix}.concurrencyControl`]: "present",
      [`${prefix}.productionDatabaseAdapter`]: "present",
      [`${prefix}.productionDatabaseAdapter.status`]: "present",
      [`${prefix}.productionDatabaseAdapter.providerClass`]: "present",
      [`${prefix}.productionDatabaseAdapter.migrationStatus`]: "present",
      [`${prefix}.productionDatabaseAdapter.backupPolicy`]: "present",
      [`${prefix}.productionDatabaseAdapter.concurrencyControl`]: "present",
      [`${prefix}.productionDatabaseAdapter.valueRedacted`]: "present",
      [`${prefix}.valueRedacted`]: "present",
    };
  }

function writeJson(baseDir: string, fileName: string, value: unknown) {
  const path = join(baseDir, fileName);
  writeFileSync(path, JSON.stringify(value));
  return path;
}
